"""Builds departure boards from a timetable feed. Usage: boards.py INPUT_DIR OUTPUT_FILE"""
import csv
import io
import json
import os
import sys
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def read_csv(directory, name):
    path = os.path.join(directory, name)
    if not os.path.exists(path):
        return []
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        text = f.read()
    rows = []
    reader = csv.reader(io.StringIO(text, newline=""))
    header = None
    for rec in reader:
        if not rec or all(c.strip() == "" for c in rec):
            continue
        if header is None:
            header = [c.strip() for c in rec]
            continue
        row = {}
        for i, h in enumerate(header):
            row[h] = rec[i].strip() if i < len(rec) else ""
        rows.append(row)
    return rows


def parse_time(s):
    h, m, sec = s.strip().split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)


def to_int(s, default=0):
    s = (s or "").strip()
    return int(s) if s else default


def parse_date(s):
    return date(int(s[0:4]), int(s[4:6]), int(s[6:8]))


_zones = {}


def zone(name):
    z = _zones.get(name)
    if z is None:
        z = _zones[name] = ZoneInfo(name)
    return z


def fmt(instant_utc, tzname):
    dt = instant_utc.astimezone(zone(tzname))
    off = dt.utcoffset()
    secs = int(off.total_seconds())
    sign = "+" if secs >= 0 else "-"
    secs = abs(secs)
    return "%04d-%02d-%02dT%02d:%02d:%02d%s%02d:%02d" % (
        dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second,
        sign, secs // 3600, (secs % 3600) // 60)


def time_origin(d, tzname):
    noon = datetime(d.year, d.month, d.day, 12, 0, 0, tzinfo=zone(tzname))
    return noon.astimezone(timezone.utc) - timedelta(hours=12)


def main(indir, outfile):
    with open(os.path.join(indir, "request.json"), "r", encoding="utf-8-sig") as f:
        request = json.load(f)
    service_dates = sorted(set(request["service_dates"]))

    agencies = read_csv(indir, "agency.txt")
    default_tz = agencies[0]["agency_timezone"]
    agency_tz = {a["agency_id"]: a["agency_timezone"] for a in agencies}
    first_agency_id = agencies[0]["agency_id"]

    stops = {s["stop_id"]: s for s in read_csv(indir, "stops.txt")}
    routes = {r["route_id"]: r for r in read_csv(indir, "routes.txt")}
    trips = {t["trip_id"]: t for t in read_csv(indir, "trips.txt")}

    calendar = {c["service_id"]: c for c in read_csv(indir, "calendar.txt")}
    exceptions = {}
    for r in read_csv(indir, "calendar_dates.txt"):
        exceptions[(r["service_id"], r["date"])] = to_int(r["exception_type"])

    freqs = {}
    for r in read_csv(indir, "frequencies.txt"):
        freqs.setdefault(r["trip_id"], []).append(r)

    st_by_trip = {}
    for r in read_csv(indir, "stop_times.txt"):
        r["_seq"] = to_int(r["stop_sequence"])
        st_by_trip.setdefault(r["trip_id"], []).append(r)

    weekdays = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]

    def runs(service_id, d):
        key = (service_id, d.strftime("%Y%m%d"))
        ex = exceptions.get(key)
        if ex == 1:
            return True
        if ex == 2:
            return False
        c = calendar.get(service_id)
        if c is None:
            return False
        if not (parse_date(c["start_date"]) <= d <= parse_date(c["end_date"])):
            return False
        return c.get(weekdays[d.weekday()], "") == "1"

    # Board stops
    def board_of(stop_id):
        s = stops[stop_id]
        parent = s.get("parent_station", "")
        if parent and parent in stops:
            return parent
        return stop_id

    board_stops = []
    for sid, s in stops.items():
        lt = to_int(s.get("location_type", ""))
        if lt == 1 or (lt == 0 and not s.get("parent_station", "")):
            board_stops.append(sid)
    board_stops.sort()

    def board_tz(sid):
        return stops[sid].get("stop_timezone", "") or default_tz

    # Pre-compute per trip: stop list with times, offsets etc (independent of date)
    trip_info = {}
    for tid, rows in st_by_trip.items():
        if tid not in trips:
            continue
        rows.sort(key=lambda r: r["_seq"])
        n = len(rows)
        times = []
        for r in rows:
            t = r.get("departure_time", "") or r.get("arrival_time", "")
            times.append(parse_time(t) if t else None)
        known = [i for i, t in enumerate(times) if t is not None]
        for i in range(n):
            if times[i] is None:
                b = max(k for k in known if k < i)
                a = min(k for k in known if k > i)
                times[i] = times[b] + ((times[a] - times[b]) * (i - b)) // (a - b)
        trip = trips[tid]
        last_stop = stops[rows[-1]["stop_id"]]
        last_name = stops[board_of(rows[-1]["stop_id"])]["stop_name"] if last_stop else ""
        route = routes[trip["route_id"]]
        label = route.get("route_short_name", "") or route.get("route_long_name", "")
        agency = route.get("agency_id", "") or first_agency_id
        deps = []
        for i, r in enumerate(rows):
            if i == n - 1:
                continue
            if to_int(r.get("pickup_type", "")) == 1:
                continue
            headsign = r.get("stop_headsign", "") or trip.get("trip_headsign", "") or last_name
            plat = stops[r["stop_id"]].get("platform_code", "") or None
            deps.append((i, r["stop_id"], headsign, plat))
        trip_info[tid] = (times, label, agency, deps)

    boards = {}
    for sid in board_stops:
        for sd in service_dates:
            boards[(sid, sd)] = []

    for sd in service_dates:
        d = date.fromisoformat(sd)
        for tid, (times, label, agency, deps) in trip_info.items():
            trip = trips[tid]
            if not runs(trip["service_id"], d):
                continue
            atz = agency_tz.get(agency, default_tz)
            origin = time_origin(d, atz)

            def inst(secs):
                return origin + timedelta(seconds=secs)

            entries = []  # (stop, bstop, headsign, plat, kind, t, until, headway)
            if tid in freqs:
                base = times[0]
                for w in freqs[tid]:
                    start = parse_time(w["start_time"])
                    end = parse_time(w["end_time"])
                    head = to_int(w["headway_secs"])
                    if start >= end or head <= 0:
                        continue
                    starts = list(range(start, end, head))
                    exact = to_int(w.get("exact_times", "")) == 1
                    for (i, stop_id, hs, plat) in deps:
                        off = times[i] - base
                        if exact:
                            for s in starts:
                                entries.append((stop_id, hs, plat, "scheduled", s + off, None, None))
                        else:
                            entries.append((stop_id, hs, plat, "interval",
                                            starts[0] + off, starts[-1] + off, head))
            else:
                for (i, stop_id, hs, plat) in deps:
                    entries.append((stop_id, hs, plat, "scheduled", times[i], None, None))

            for (stop_id, hs, plat, kind, t, until, head) in entries:
                bs = board_of(stop_id)
                if (bs, sd) not in boards:
                    continue
                btz = board_tz(bs)
                it = inst(t)
                dep = {
                    "kind": kind,
                    "time": fmt(it, btz),
                    "until": fmt(inst(until), btz) if until is not None else None,
                    "headway_secs": head,
                    "route": label,
                    "headsign": hs,
                    "trip": tid,
                    "platform": plat,
                    "agency": agency,
                }
                key = (it, label, hs, tid, (0, "") if plat is None else (1, plat))
                boards[(bs, sd)].append((key, dep))

    out_boards = []
    for sid in board_stops:
        for sd in service_dates:
            lst = boards[(sid, sd)]
            lst.sort(key=lambda x: x[0])
            out_boards.append({
                "stop_id": sid,
                "name": stops[sid]["stop_name"],
                "timezone": board_tz(sid),
                "service_date": sd,
                "departures": [x[1] for x in lst],
            })

    with open(outfile, "w", encoding="utf-8") as f:
        json.dump({"service_dates": service_dates, "boards": out_boards}, f, ensure_ascii=False)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
